import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "./PropertyAssessmentDetails.css";

function PropertyAssessmentDetails() {
  const { part1, part2 } = useParams();
  const navigate = useNavigate();

  // Handle different URL patterns
  const propertyNo = part2 ? `${part1}/${part2}` : part1;
  
  const [property, setProperty] = useState(null);
  const [assessment, setAssessment] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchData = async () => {
    setLoading(true);
    setError(null);

    try {
      console.log("Fetching data for propertyNo:", propertyNo);
      
      const encodedPropertyNo = encodeURIComponent(propertyNo);
      console.log("Encoded propertyNo:", encodedPropertyNo);
      
      // Fetch property details
      const propertyResponse = await axios.get(
        `http://localhost:5001/properties/propertyNo/${encodedPropertyNo}`,
        { timeout: 10000 }
      );

      if (propertyResponse.data?.property) {
        setProperty(propertyResponse.data.property);
      } else {
        setError({ message: "Property not found", status: 404 });
        return;
      }

      // Fetch assessment details
      try {
        const assessmentResponse = await axios.get(
          `http://localhost:5001/assessments/propertyNo/${encodedPropertyNo}`,
          { timeout: 10000 }
        );

        if (assessmentResponse.data?.assessment) {
          setAssessment(assessmentResponse.data.assessment);
        } else {
          setAssessment(null);
        }
      } catch (assessmentError) {
        if (assessmentError.response?.status === 404) {
          setAssessment(null);
        } else {
          console.error("Assessment error:", assessmentError);
          setAssessment(null);
        }
      }
    } catch (err) {
      setError({
        message: err.response?.data?.message || err.message,
        status: err.response?.status,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (propertyNo) {
      fetchData();
    }
  }, [propertyNo]);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading property details for: {propertyNo}</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-container">
        <h3>Error Loading Data</h3>
        <p>{error.message}</p>
        <p>Property Number: {propertyNo}</p>
        {error.status === 404 ? (
          <div>
            <p>Property not found. Please check the property number.</p>
            <button onClick={() => navigate('/')} className="back-button">
              Go to Home
            </button>
          </div>
        ) : (
          <button onClick={fetchData} className="retry-button">
            Retry
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="details-container">
      <div className="header-section">
        <h2>Details of Property</h2>
        <button onClick={() => navigate(-1)} className="back-button">
          &larr; Back
        </button>
      </div>

      {property && (
        <>
          {/* Property Details Section */}
          <div className="details-section property-section">
            <h3>Property Information</h3>
            <div className="detail-grid">
              <DetailItem label="Related Office" value={property.office} />
              <DetailItem label="Division" value={property.division} />
              <DetailItem label="Street Name" value={property.street} />
              <DetailItem label="Property No" value={property.propertyNo} />
              <DetailItem label="Custom No" value={property.customNo} />
              <DetailItem label="Owner Name" value={property.ownerName} />
              <DetailItem label="Description" value={property.description} />
              <DetailItem label="Annual Value / Quarter Rate" value={property.annualValue} />
              <DetailItem label="Arrears" value={property.arrears} />
              <DetailItem label="Warrent" value={property.warrent} />
              <DetailItem label="Year Rate" value={property.yearRate} />
              <DetailItem label="Future" value={property.future} />
              <DetailItem label="Discount" value={property.discount} />
            </div>
          </div>

          {/* Go to Payment Button */}
          <div className="payment-button-container">
            <button
              onClick={() => navigate("/payment", { state: { propertyNo } })}
              className="go-to-payment-button"
            >
              Go to Payment
            </button>
          </div>
        </>
      )}
    </div>
  );
}

// Reusable detail component
const DetailItem = ({ label, value }) => (
  <div className="detail-item">
    <span className="detail-label">{label}:</span>
    <span className="detail-value">{value || "-"}</span>
  </div>
);

export default PropertyAssessmentDetails;
